(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[120]={"source_order":120,"notes":["The faint show-through could conceal very faint pencil writing on this page; no independent target-page writing was distinguished on inspection of the native tiles.","The coordinates for the lower-right smudge are approximate because it lies at the overlap of the tiles.","Faint ghost text across the ruled lines appears to be show-through/offset from the written leaf (fol. 60). It is not target-page writing and has not been inventoried as blocks.","The thread visible at the right edge is binding, not a mark.","The native tiles were reviewed across the whole canvas: top, middle, bottom, left (gutter) margin, right (outer) margin and interlinear spaces. No catalogue entries, headings, cross-references or annotations were found apart from the folio number.","Faint ghost lettering across the ruled lines is show-through or offset from the written leaf (fol. 60, source order 119). It is not transcribed as target-page writing.","Several non-text marks were seen and none is legible as text: an ink blot near the left at about [475,2000]; an ink smudge near the right edge at about [2920,2935]; faint grey specks below the folio number; a faint grey smudge mid-page at about [2240,1640]; a faint curved stroke at about [515,2655]; and a pale smudge near the lower right.","The thread visible at the right edge is binding.","The inventory coordinates for the lower-right pale smudge fall outside the canvas. The visible smudge is at about [3060,3826,65,45].","Faint ghost lettering across the ruled lines appears to be show-through or offset from fol. 60. Very faint pencil writing on this page cannot be absolutely excluded, though none could be distinguished."],"records":[{"id":"css-prod-0120-r001","local_id":"r001","source_order":120,"folio":"60b","folio_label":"fol. 60b","sequence":1,"page_id":"54a5c5e3-c6f4-4973-a6f1-3b84a8ff93d2","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"60b.","annotations":["Pencil folio number in the top-left corner.","The 'b' is written superscript and is followed by a point, so the visual form is 60ᵇ."],"uncertainties":["The inventory coordinates for the lower-right pale smudge fall outside the canvas. The visible smudge is at about [3060,3826,65,45].","Faint ghost lettering across the ruled lines appears to be show-through or offset from fol. 60. Very faint pencil writing on this page cannot be absolutely excluded, though none could be distinguished."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[420,285,145,95]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/54a5c5e3-c6f4-4973-a6f1-3b84a8ff93d2.json","auditPath":"audit/pages/0120.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
